177	    /** Per (fixture, node_name): the 5 reference metrics [qlen, util, respt, residt, tput].
178	     *  Filters rows by solver label (e.g. "LN" or "LQNS"). */
179	    static Map<String, Map<String, double[]>> loadReference(String csvPath, String solverLabel) throws Exception {
180	        Map<String, Map<String, double[]>> ref = new HashMap<String, Map<String, double[]>>();
181	        BufferedReader br = new BufferedReader(new FileReader(csvPath));
182	        String line = br.readLine();  // header
183	        // columns: fixture_name,partition,condition,solver,node_name,node_type,server_count,qlen,util,respt,residt,tput
184	        while ((line = br.readLine()) != null) {
185	            String[] f = line.split(",", -1);
186	            if (f.length < 12) continue;
187	            if (!solverLabel.equals(f[3])) continue;
188	            String fixture = f[0];
189	            String node = f[4];
190	            double q = parseD(f[7]);
191	            double u = parseD(f[8]);
192	            double rt = parseD(f[9]);
193	            double rd = parseD(f[10]);
194	            double t = parseD(f[11]);
195	            ref.computeIfAbsent(fixture, k -> new HashMap<String, double[]>())
196	                    .put(node, new double[]{q, u, rt, rd, t});
197	        }
198	        br.close();
199	        return ref;
200	    }
