207	    private static double parseD(String s) {
208	        if (s == null || s.isEmpty() || "NaN".equalsIgnoreCase(s)) return Double.NaN;
209	        if ("Infinity".equalsIgnoreCase(s)) return Double.POSITIVE_INFINITY;
210	        if ("-Infinity".equalsIgnoreCase(s)) return Double.NEGATIVE_INFINITY;
211	        try { return Double.parseDouble(s); } catch (NumberFormatException e) { return Double.NaN; }
212	    }
213	
214	    /** atol=1e-3, rtol=5e-2 slack; NaN-vs-NaN -> 0; NaN-vs-finite -> NaN (skipped). */
215	    private static double slack(double expected, double actual) {
216	        return slackWith(expected, actual, ATOL, RTOL);
217	    }
218	
219	    private static double slackWith(double expected, double actual, double atol, double rtol) {
220	        if (Double.isNaN(expected) && Double.isNaN(actual)) return 0.0;
221	        if (Double.isNaN(expected) || Double.isNaN(actual)) return Double.NaN;
222	        double diff = Math.abs(expected - actual);
223	        double allowed = atol + rtol * Math.abs(expected);
224	        return diff / allowed;
225	    }
226	
227	    /** Match-either rule: per-metric slack is the min of (vs-LN with strict
228	     *  tol) and (vs-LQNS with loose tol). NaN-vs-NaN returns 0; finite-vs-NaN
229	     *  on one side falls through to the comparable side; NaN on both → NaN
230	     *  (caller skips). Mirrors {@code util.minSkipNaN}. */
231	    private static double slackEither(double lnExp, double lqnsExp, double actual) {
232	        double sLn   = slackWith(lnExp,   actual, ATOL,      RTOL);
233	        double sLqns = slackWith(lqnsExp, actual, LQNS_ATOL, LQNS_RTOL);
234	        boolean aNaN = Double.isNaN(sLn);
235	        boolean bNaN = Double.isNaN(sLqns);
236	        if (aNaN && bNaN) return Double.NaN;
237	        if (aNaN) return sLqns;
238	        if (bNaN) return sLn;
239	        return Math.min(sLn, sLqns);
240	    }
