261	    public static FixtureResult runOne(String fixtureName,
262	                                       Supplier<LayeredNetwork> factory,
263	                                       Map<String, double[]> ref,
264	                                       int warmup, int repeats) {
265	        return runOne(fixtureName, factory, ref, null, warmup, repeats);
266	    }
267	
268	    public static FixtureResult runOne(String fixtureName,
269	                                       Supplier<LayeredNetwork> factory,
270	                                       Map<String, double[]> lnRef,
271	                                       Map<String, double[]> lqnsRef,
272	                                       int warmup, int repeats) {
273	        // JIT warmup — untimed runs to settle compilation
274	        for (int w = 0; w < warmup; w++) {
275	            LayeredNetwork m = factory.get();
276	            SolverLNSimple s = new SolverLNSimple(m);
277	            int[] iters = {0};
278	            s.iterateCoupledMva(() -> iters[0]++);
279	        }
280	
281	        // Timed runs
282	        long[] times = new long[repeats];
283	        int iters = -1;
284	        LayeredNetworkAvgTable lastTable = null;
285	        for (int r = 0; r < repeats; r++) {
286	            LayeredNetwork m = factory.get();
287	            SolverLNSimple s = new SolverLNSimple(m);
288	            int[] it = {0};
289	            long t0 = System.nanoTime();
290	            s.iterateCoupledMva(() -> it[0]++);
291	            long t1 = System.nanoTime();
292	            times[r] = (t1 - t0) / 1_000_000L;
293	            iters = it[0];
294	            lastTable = s.getAvgTable();
295	        }
296	        long[] sorted = times.clone();
297	        Arrays.sort(sorted);
298	        long med = sorted[sorted.length / 2];
299	        long mn = sorted[0];
300	        long mx = sorted[sorted.length - 1];
301	
302	        // Correctness vs cached LN (strict) and LQNS (loose) references —
303	        // match-either rule: per (node, metric), pass if EITHER reference is
304	        // within tolerance. Mirrors the existing util.assertResultsMatchSolverLN
305	        // semantic where LNSimple is accepted if it tracks LN OR LQNS.
306	        double maxSlack = 0.0;
307	        String worstMsg = null;
308	        int compared = 0;
309	        if (lastTable != null && lnRef != null) {
310	            List<String> names = lastTable.getNodeNames();
311	            List<Double> q = lastTable.getQLen();
312	            List<Double> u = lastTable.getUtil();
313	            List<Double> rt = lastTable.getRespT();
314	            List<Double> rd = lastTable.getResidT();
315	            List<Double> tp = lastTable.getTput();
316	            String[] metrics = {"QLen", "Util", "RespT", "ResidT", "Tput"};
317	            for (int i = 0; i < names.size(); i++) {
318	                String node = names.get(i);
319	                double[] lnRow   = lnRef.get(node);
320	                double[] lqnsRow = lqnsRef != null ? lqnsRef.get(node) : null;
321	                if (lnRow == null && lqnsRow == null) continue;
322	                double[] actual = {q.get(i), u.get(i), rt.get(i), rd.get(i), tp.get(i)};
323	                for (int mi = 0; mi < 5; mi++) {
324	                    double lnExp   = lnRow   != null ? lnRow[mi]   : Double.NaN;
325	                    double lqnsExp = lqnsRow != null ? lqnsRow[mi] : Double.NaN;
326	                    double s = (lqnsRow != null)
327	                            ? slackEither(lnExp, lqnsExp, actual[mi])
328	                            : slack(lnExp, actual[mi]);
329	                    if (Double.isNaN(s)) continue;
330	                    compared++;
331	                    if (s > maxSlack) {
332	                        maxSlack = s;
333	                        worstMsg = String.format("%s.%s: LNSimple=%.6f vs LN=%.6f LQNS=%.6f slack=%.3f",
334	                                node, metrics[mi], actual[mi], lnExp, lqnsExp, s);
335	                    }
336	                }
337	            }
338	        }
339	        boolean pass = maxSlack <= 1.0;
340	        FixtureResult fr = new FixtureResult(fixtureName, iters, med, mn, mx, maxSlack, worstMsg, pass,
341	                compared, times);
342	        fr.lastTable = lastTable;
343	        return fr;
344	    }
