382	        PrintStream origOut = System.out;
383	        PrintStream origErr = System.err;
384	        java.io.OutputStream nullOut = new java.io.OutputStream() {
385	            @Override public void write(int b) {}
386	            @Override public void write(byte[] b, int o, int l) {}
387	        };
388	        PrintStream sink = new PrintStream(nullOut);
389	
390	        List<FixtureResult> results = new ArrayList<FixtureResult>();
391	        long globalStart = System.currentTimeMillis();
392	        int failed = 0;
393	
394	        // Access-layer scale diagnostic (opt-in): add the large no-precedence
395	        // TempActivityFixtures. They have no LN reference (timing-only), so they
396	        // are timed but not pass/fail-checked. Default off → 61-corpus unchanged.
397	        if ("true".equalsIgnoreCase(System.getProperty("fasteval.bigfix", "false"))) {
398	            for (Map.Entry<String, Supplier<LayeredNetwork>> be
399	                    : jline.solvers.ln_simple.fixtures.TempActivityFixtures.big().entrySet()) {
400	                FIXTURES.put(be.getKey(), be.getValue());
401	            }
402	        }
403	
404	        // Cross-fixture JVM warmup: run the smallest fixture a few times before
405	        // any timed work, so the first measured fixture isn't penalised.
406	        Supplier<LayeredNetwork> warmupFactory = FIXTURES.get("A1_chain_d3_N20");
407	        if (warmupFactory != null) {
408	            System.setOut(sink); System.setErr(sink);
409	            try {
410	                for (int w = 0; w < 3; w++) {
411	                    LayeredNetwork m = warmupFactory.get();
412	                    new SolverLNSimple(m).iterateCoupledMva(() -> {});
413	                }
414	            } finally {
415	                System.setOut(origOut); System.setErr(origErr);
416	            }
417	        }
418	
419	        for (Map.Entry<String, Supplier<LayeredNetwork>> e : FIXTURES.entrySet()) {
420	            String name = e.getKey();
421	            if (!filter.isEmpty()) {
422	                boolean match = false;
423	                for (String pat : filter.split(",")) {
424	                    pat = pat.trim();
425	                    if (pat.endsWith("*")) {
426	                        if (name.startsWith(pat.substring(0, pat.length() - 1))) { match = true; break; }
427	                    } else if (name.equals(pat)) { match = true; break; }
428	                }
429	                if (!match) continue;
430	            }
431	            System.setOut(sink); System.setErr(sink);
432	            FixtureResult fr;
433	            try {
434	                Map<String, double[]> lqnsRow = lqnsRef != null ? lqnsRef.get(name) : null;
435	                fr = runOne(name, e.getValue(), ref.get(name), lqnsRow, warmup, repeats);
436	            } finally {
437	                System.setOut(origOut); System.setErr(origErr);
438	            }
439	            results.add(fr);
440	            String status;
441	            if (fr.pass) {
442	                status = "PASS";
443	            } else if (KNOWN_BASELINE_FAILURES.contains(fr.name)) {
444	                Double ceiling = BASELINE_FAIL_SLACK.get(fr.name);
445	                if (ceiling != null && fr.maxSlack <= ceiling * (1.0 + REGRESSION_TOL)) {
446	                    status = "KNOWN-FAIL (no regression)";
447	                } else {
448	                    status = String.format("REGRESSION over known baseline (%.3f > %.3f) %s",
449	                            fr.maxSlack, ceiling, fr.worstMsg == null ? "" : fr.worstMsg);
450	                    failed++;
451	                }
452	            } else {
453	                status = "FAIL  " + (fr.worstMsg == null ? "" : fr.worstMsg);
454	                failed++;
455	            }
456	            origOut.printf("%-45s iter=%2d  time_med=%5d ms  time_min=%5d ms  slack=%.3f  %s%n",
457	                    fr.name, fr.iters, fr.timeMsMedian, fr.timeMsMin, fr.maxSlack, status);
458	        }
459	
460	        long elapsed = System.currentTimeMillis() - globalStart;
461	
462	        // Aggregates
463	        int totalIters = 0;
464	        long totalTimeMs = 0;
465	        for (FixtureResult fr : results) {
466	            totalIters += fr.iters;
467	            totalTimeMs += fr.timeMsMedian;
468	        }
469	        origOut.printf("%n=== FastEval summary: %d fixtures, %d failed, total elapsed %.1f s ===%n",
470	                results.size(), failed, elapsed / 1000.0);
471	        origOut.printf("Total iters: %d   Total median time: %d ms%n", totalIters, totalTimeMs);
472	
473	        // Write per-fixture CSV
474	        java.io.File outFile = new java.io.File(outPath);
475	        outFile.getParentFile().mkdirs();
476	        BufferedWriter bw = new BufferedWriter(new FileWriter(outFile));
477	        bw.write("fixture_name,iters,time_ms_median,time_ms_min,time_ms_max,max_slack_vs_ln,nodes_compared,pass,all_times_ms\n");
478	        for (FixtureResult fr : results) {
479	            StringBuilder sb = new StringBuilder();
480	            for (int i = 0; i < fr.timesMs.length; i++) {
481	                if (i > 0) sb.append('|');
482	                sb.append(fr.timesMs[i]);
483	            }
484	            bw.write(String.format("%s,%d,%d,%d,%d,%.6f,%d,%s,%s%n",
485	                    fr.name, fr.iters, fr.timeMsMedian, fr.timeMsMin, fr.timeMsMax,
486	                    fr.maxSlack, fr.nodesCompared, fr.pass ? "true" : "false", sb.toString()));
487	        }
488	        bw.close();
489	        origOut.printf("Wrote: %s%n", outPath);
490	
491	        // S2-E11b: optional metric-table dump for cross-config diffing.
492	        if (!tableDumpPath.isEmpty()) {
493	            java.io.File td = new java.io.File(tableDumpPath);
494	            td.getParentFile().mkdirs();
495	            BufferedWriter tw = new BufferedWriter(new FileWriter(td));
496	            tw.write("fixture,node,qlen,util,respt,residt,tput\n");
497	            for (FixtureResult fr : results) {
498	                if (fr.lastTable == null) continue;
499	                List<String> ns = fr.lastTable.getNodeNames();
500	                List<Double> q  = fr.lastTable.getQLen();
501	                List<Double> u  = fr.lastTable.getUtil();
502	                List<Double> rt = fr.lastTable.getRespT();
503	                List<Double> rd = fr.lastTable.getResidT();
504	                List<Double> tp = fr.lastTable.getTput();
505	                for (int i = 0; i < ns.size(); i++) {
506	                    tw.write(String.format("%s,%s,%.10g,%.10g,%.10g,%.10g,%.10g%n",
507	                            fr.name, ns.get(i), q.get(i), u.get(i),
508	                            rt.get(i), rd.get(i), tp.get(i)));
509	                }
510	            }
511	            tw.close();
512	            origOut.printf("Wrote tables: %s%n", tableDumpPath);
513	        }
514	
515	        // Study: verify the LqnGraph ablation flags flip the code paths claimed.
516	        if (jline.solvers.ln_simple.LqnGraph.COUNT) {
517	            origOut.println("LQNCOUNT " + jline.solvers.ln_simple.LqnGraph.debugCounters());
518	        }
519	
520	        if (failed > 0) {
521	            System.exit(1);
522	        }
523	    }
524	}
